namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = ""; // e.g. "CS", "MATH"
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = ""; // e.g. "CS101"
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = ""; // e.g. "MWF 9:00-9:50 AM"
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^\d{6,10}$", ErrorMessage = "Student ID must be 6-10 digits.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

namespace UniversityCourseCatalog.Services;

using UniversityCourseCatalog.Models;

public interface ICatalogService
{
    List<Department> GetDepartments();
    Department? GetDepartment(int id);
    List<Course> GetCourses(string? search = null, int? departmentId = null);
    Course? GetCourse(int id);
    List<Course> GetFeaturedCourses();
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

namespace UniversityCourseCatalog.Services;

using UniversityCourseCatalog.Models;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new Department { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new Department { Id = 2, Name = "Mathematics", Code = "MATH", Description = "The science of numbers, quantity, and space." },
            new Department { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new Department { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and the English language." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new Course { Id = 1, DepartmentId = 1, CourseCode = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "MWF 9:00-9:50 AM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory programming and has authored two textbooks on Python.", IsFeatured = true },
            new Course { Id = 2, DepartmentId = 1, CourseCode = "CS201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and associated algorithms for searching and sorting.", Credits = 4, Schedule = "TTh 10:30-11:50 AM", InstructorName = "Dr. Bob Martinez", InstructorBio = "Dr. Martinez specializes in algorithm design and has published extensively on graph theory.", IsFeatured = true },
            new Course { Id = 3, DepartmentId = 1, CourseCode = "CS301", Title = "Database Systems", Description = "Introduction to database design, SQL, normalization, and transaction management. Covers both relational and NoSQL databases.", Credits = 3, Schedule = "MWF 1:00-1:50 PM", InstructorName = "Dr. Carol Wu", InstructorBio = "Dr. Wu worked in industry for 10 years at major tech companies before joining academia." },
            new Course { Id = 4, DepartmentId = 1, CourseCode = "CS401", Title = "Software Engineering", Description = "Principles of software development including agile methodologies, design patterns, testing, and project management.", Credits = 3, Schedule = "TTh 2:00-3:20 PM", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory programming and has authored two textbooks on Python." },

            // Mathematics
            new Course { Id = 5, DepartmentId = 2, CourseCode = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "MWF 8:00-8:50 AM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is an award-winning mathematics educator with a passion for making calculus accessible to all students.", IsFeatured = true },
            new Course { Id = 6, DepartmentId = 2, CourseCode = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations with applications.", Credits = 3, Schedule = "TTh 9:00-10:20 AM", InstructorName = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi's research focuses on numerical linear algebra and its applications in machine learning." },
            new Course { Id = 7, DepartmentId = 2, CourseCode = "MATH301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00-11:50 AM", InstructorName = "Dr. David Park", InstructorBio = "Dr. Park is an award-winning mathematics educator with a passion for making calculus accessible to all students." },
            new Course { Id = 8, DepartmentId = 2, CourseCode = "MATH401", Title = "Differential Equations", Description = "Ordinary differential equations, systems of equations, Laplace transforms, and numerical methods.", Credits = 4, Schedule = "TTh 1:00-2:20 PM", InstructorName = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi's research focuses on numerical linear algebra and its applications in machine learning." },

            // Physics
            new Course { Id = 9, DepartmentId = 3, CourseCode = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "MWF 10:00-10:50 AM", InstructorName = "Dr. Frank Thompson", InstructorBio = "Dr. Thompson is an experimental physicist who has worked at CERN and brings real-world research experience to the classroom.", IsFeatured = true },
            new Course { Id = 10, DepartmentId = 3, CourseCode = "PHYS201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Continuation of General Physics I.", Credits = 4, Schedule = "TTh 10:30-11:50 AM", InstructorName = "Dr. Grace Liu", InstructorBio = "Dr. Liu specializes in quantum optics and has received multiple teaching excellence awards." },
            new Course { Id = 11, DepartmentId = 3, CourseCode = "PHYS301", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and applications to atomic physics.", Credits = 3, Schedule = "MWF 2:00-2:50 PM", InstructorName = "Dr. Grace Liu", InstructorBio = "Dr. Liu specializes in quantum optics and has received multiple teaching excellence awards." },

            // English
            new Course { Id = 12, DepartmentId = 4, CourseCode = "ENG101", Title = "English Composition", Description = "Develop critical thinking and writing skills through essay composition, research writing, and rhetorical analysis.", Credits = 3, Schedule = "MWF 9:00-9:50 AM", InstructorName = "Prof. Hannah Brooks", InstructorBio = "Prof. Brooks is a published author and writing consultant with expertise in academic and creative writing." },
            new Course { Id = 13, DepartmentId = 4, CourseCode = "ENG201", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, examining major authors and literary movements.", Credits = 3, Schedule = "TTh 11:00-12:20 PM", InstructorName = "Dr. Ian Wallace", InstructorBio = "Dr. Wallace is a literary critic specializing in 20th-century American fiction and has published three books on the subject." },
            new Course { Id = 14, DepartmentId = 4, CourseCode = "ENG301", Title = "Creative Writing", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction. Students develop a portfolio of original work.", Credits = 3, Schedule = "TTh 2:00-3:20 PM", InstructorName = "Prof. Hannah Brooks", InstructorBio = "Prof. Brooks is a published author and writing consultant with expertise in academic and creative writing." },
            new Course { Id = 15, DepartmentId = 4, CourseCode = "ENG401", Title = "Shakespeare", Description = "In-depth study of Shakespeare's major plays including tragedies, comedies, and histories in their historical context.", Credits = 3, Schedule = "MWF 1:00-1:50 PM", InstructorName = "Dr. Ian Wallace", InstructorBio = "Dr. Wallace is a literary critic specializing in 20th-century American fiction and has published three books on the subject." }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return request.CourseId > 0 && _courses.Any(c => c.Id == request.CourseId);
    }
}

