@page "/courses"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses">
    <div class="row mb-3">
        <div class="col-md-5">
            <input type="text" name="Search" value="@Search" class="form-control" placeholder="Search courses..." />
        </div>
        <div class="col-md-4">
            <select name="DepartmentId" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in CatalogService.GetDepartments())
                {
                    <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-3">
            <button type="submit" class="btn btn-primary">Search</button>
        </div>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <p>No courses found.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                var dept = CatalogService.GetDepartment(course.DepartmentId);
                <tr>
                    <td>@course.CourseCode</td>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td><a href="courses/@course.Id">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
}
else
{
    var dept = CatalogService.GetDepartment(course.DepartmentId);

    <PageTitle>@course.Title</PageTitle>

    <h1>@course.Title</h1>
    <p><strong>@course.CourseCode</strong> &middot; @dept?.Name</p>

    <h2>Description</h2>
    <p>@course.Description</p>

    <h2>Details</h2>
    <ul>
        <li><strong>Credits:</strong> @course.Credits</li>
        <li><strong>Schedule:</strong> @course.Schedule</li>
    </ul>

    <h2>Instructor</h2>
    <p><strong>@course.InstructorName</strong></p>
    <p>@course.InstructorBio</p>

    <div class="mt-3">
        <a href="courses" class="btn btn-secondary me-2">Back to Courses</a>
        <a href="enroll?CourseId=@course.Id" class="btn btn-primary">Enroll in This Course</a>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private UniversityCourseCatalog.Models.Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for the selected course has been received. You will receive a confirmation email shortly.</p>
    </div>
    <a href="courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
        <AntiforgeryToken />
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="mb-3">
            <label for="studentName" class="form-label">Student Name</label>
            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                <option value="0">-- Select a course --</option>
                @foreach (var course in CatalogService.GetCourses())
                {
                    <option value="@course.Id">@course.CourseCode - @course.Title</option>
                }
            </InputSelect>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var success = CatalogService.SubmitEnrollmentRequest(Model);
        if (success)
        {
            submitted = true;
        }
    }
}

